#!/usr/bin/env python3
"""Residents survey crosstabs: python3 crosstabs.py INPUT_DIR OUTPUT_FILE"""
import csv
import io
import json
import os
import re
import sys
from datetime import datetime, timedelta, timezone
from fractions import Fraction


def read_exports(d):
    rows = []
    edir = os.path.join(d, "exports")
    names = sorted(n for n in os.listdir(edir)
                   if n.endswith(".csv") and os.path.isfile(os.path.join(edir, n)))
    for n in names:
        with open(os.path.join(edir, n), "rb") as f:
            text = f.read().decode("utf-8")
        if text.startswith("\ufeff"):
            text = text[1:]
        first = text.split("\n", 1)[0].rstrip("\r")
        delim = next((c for c in (",", ";", "\t") if c in first), ",")
        reader = csv.reader(io.StringIO(text, newline=""), delimiter=delim)
        header = None
        for cells in reader:
            cells = [c.strip() for c in cells]
            if header is None:
                header = cells
                continue
            if not any(cells):
                continue
            row = {}
            for i, h in enumerate(header):
                v = cells[i] if i < len(cells) else ""
                row[h] = v if v != "" else None
            rows.append(row)
    return rows


def parse_time(s, meta):
    if meta.get("submitted_format") == "local":
        dt = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        off = meta.get("utc_offset", "+00:00")
        sign = -1 if off[0] == "-" else 1
        h, m = off[1:].split(":")
        tz = timezone(sign * timedelta(hours=int(h), minutes=int(m)))
        return dt.replace(tzinfo=tz).astimezone(timezone.utc)
    m = re.match(r"^(\d{4}-\d\d-\d\d)T(\d\d:\d\d:\d\d)(\.\d+)?(Z|[+-]\d\d:\d\d)$", s)
    dt = datetime.strptime(m.group(1) + " " + m.group(2), "%Y-%m-%d %H:%M:%S")
    if m.group(3):
        dt = dt.replace(microsecond=int(float(m.group(3)) * 1e6))
    z = m.group(4)
    if z == "Z":
        tz = timezone.utc
    else:
        sign = -1 if z[0] == "-" else 1
        tz = timezone(sign * timedelta(hours=int(z[1:3]), minutes=int(z[4:6])))
    return dt.replace(tzinfo=tz).astimezone(timezone.utc)


def parse_duration(s, meta):
    if meta.get("duration_format") == "clock":
        p = [int(x) for x in s.split(":")]
        t = 0
        for x in p:
            t = t * 60 + x
        return t
    return int(float(s))


def median(vals):
    v = sorted(vals)
    n = len(v)
    if n % 2:
        return Fraction(v[n // 2])
    return Fraction(v[n // 2 - 1] + v[n // 2], 2)


def to_int(s):
    try:
        return int(s)
    except ValueError:
        return int(float(s))


def apply_recode(entry, v):
    rc = entry.get("recode")
    if rc is not None:
        return rc[v]
    return to_int(v)


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    cb = json.load(open(os.path.join(indir, "codebook.json"), encoding="utf-8"))
    wt = json.load(open(os.path.join(indir, "weighting.json"), encoding="utf-8"))
    plan = json.load(open(os.path.join(indir, "tables.json"), encoding="utf-8"))
    versions = cb["versions"]
    questions = cb["questions"]
    qmap = {q["id"]: q for q in questions}

    raw = read_exports(indir)
    recs = []
    for r in raw:
        ver = r.get("form_version")
        meta = versions[ver]["meta"]
        status = r.get(meta["status"])
        complete = status == meta["complete"]
        lp = r.get(meta["last_page"])
        recs.append({
            "row": r, "ver": ver, "meta": meta, "complete": complete,
            "id": r.get(meta["id"]),
            "time": parse_time(r[meta["submitted"]], meta) if r.get(meta["submitted"]) else None,
            "dur": parse_duration(r[meta["duration"]], meta) if r.get(meta["duration"]) else None,
            "page": versions[ver]["pages"] if complete else (to_int(lp) if lp is not None else 0),
        })

    stats = {k: {"rows": 0, "duplicates": 0, "short_partials": 0, "speeders": 0,
                 "complete": 0, "partial": 0} for k in versions}
    for rc in recs:
        stats[rc["ver"]]["rows"] += 1

    # 1. duplicates
    best = {}
    order = []
    for rc in recs:
        k = rc["id"]
        if k not in best:
            best[k] = rc
            order.append(k)
            continue
        cur = best[k]
        def rank(x):
            return (1 if x["complete"] else 0, x["time"].timestamp() if x["time"] else float("-inf"))
        if rank(rc) > rank(cur):
            stats[cur["ver"]]["duplicates"] += 1
            best[k] = rc
        else:
            stats[rc["ver"]]["duplicates"] += 1
    kept = [best[k] for k in order]

    # 2. short partials
    pmin = cb.get("partial_min_page", 0)
    k2 = []
    for rc in kept:
        if not rc["complete"] and rc["page"] < pmin:
            stats[rc["ver"]]["short_partials"] += 1
        else:
            k2.append(rc)

    # 3. speeders
    med = {}
    for v in versions:
        d = [rc["dur"] for rc in k2 if rc["ver"] == v and rc["complete"] and rc["dur"] is not None]
        if d:
            med[v] = median(d)
    k3 = []
    for rc in k2:
        if rc["complete"] and rc["dur"] is not None and rc["ver"] in med \
                and rc["dur"] * 5 < med[rc["ver"]] * 2:
            stats[rc["ver"]]["speeders"] += 1
        else:
            k3.append(rc)
    kept = k3
    for rc in kept:
        stats[rc["ver"]]["complete" if rc["complete"] else "partial"] += 1

    # answers
    ref_year = int(cb["reference_date"][:4])

    def read_answer(q, rc):
        """Return valid answer: None, int code, or frozenset of codes."""
        ent = q["versions"][rc["ver"]]
        row = rc["row"]
        t = q["type"]
        if t == "multi":
            chosen = set()
            if "columns" in ent:
                for code, col in ent["columns"].items():
                    if row.get(col) == "1":
                        chosen.add(int(code))
            else:
                cell = row.get(ent["column"])
                if cell is not None:
                    for el in cell.split(ent["separator"]):
                        el = el.strip()
                        if el:
                            chosen.add(apply_recode(ent, el))
            if not chosen:
                return None
            excl = {o["code"] for o in q["options"] if o.get("exclusive")}
            if chosen & excl:
                if chosen - excl:
                    chosen -= excl
                elif len(chosen) >= 2:
                    return None
            miss = {o["code"] for o in q["options"] if o.get("missing")}
            chosen -= miss
            return frozenset(chosen) if chosen else None
        v = row.get(ent["column"])
        if v is None:
            return None
        if t == "age":
            src = ent.get("source")
            if src == "band":
                code = apply_recode(ent, v)
                return code
            age = to_int(v)
            if src == "birth_year":
                age = ref_year - age
            for b in q["bands"]:
                if b["min"] <= age <= b["max"]:
                    return b["code"]
            return None
        code = apply_recode(ent, v)
        if any(o["code"] == code and o.get("missing") for o in q["options"]):
            return None
        return code

    def holds(cond, asked, ans):
        if not asked.get(cond["question"]):
            return False
        a = ans.get(cond["question"])
        if a is None:
            return False
        if isinstance(a, frozenset):
            return bool(a & set(cond["codes"]))
        return a in cond["codes"]

    for rc in kept:
        asked, ans = {}, {}
        for q in questions:
            ent = q["versions"].get(rc["ver"])
            ok = ent is not None and (rc["complete"] or ent["page"] <= rc["page"])
            if ok and q.get("ask_if"):
                ok = holds(q["ask_if"], asked, ans)
            asked[q["id"]] = ok
            ans[q["id"]] = read_answer(q, rc) if ok else None
        rc["asked"], rc["ans"] = asked, ans

    n = len(kept)

    # weighting
    w = [1.0] * n
    dims = []
    for d in wt["dimensions"]:
        qid = d["question"]
        present = {rc["ans"][qid] for rc in kept if rc["ans"].get(qid) is not None}
        tg = {int(c): float(t) for c, t in d["targets"].items() if int(c) in present}
        tot = sum(tg.values())
        if not tg or tot <= 0:
            continue
        shares = {c: t / tot for c, t in tg.items()}
        cat = [rc["ans"][qid] if rc["ans"].get(qid) in shares else None for rc in kept]
        dims.append((shares, cat))
    if n:
        for _ in range(wt.get("max_iterations", 100)):
            converged = True
            for shares, cat in dims:
                T = sum(w[i] for i in range(n) if cat[i] is not None)
                W = {}
                for i in range(n):
                    if cat[i] is not None:
                        W[cat[i]] = W.get(cat[i], 0.0) + w[i]
                f = {}
                for c, s in shares.items():
                    f[c] = s * T / W[c] if W.get(c) else 1.0
                    if abs(f[c] - 1) > wt.get("tolerance", 1e-10):
                        converged = False
                for i in range(n):
                    if cat[i] is not None:
                        w[i] *= f[cat[i]]
            if converged:
                break
        m = sum(w) / n
        hi, lo = wt["cap"] * m, wt["floor"] * m
        w = [min(max(x, lo), hi) for x in w]
        m2 = sum(w) / n
        w = [x / m2 for x in w]

    # tables
    def r2(x):
        return None if x is None else round(x + 0.0, 2)

    banner_cols = [("total", None, None)]
    for bq in plan["banner"]:
        q = qmap[bq]
        opts = q["bands"] if q["type"] == "age" else [o for o in q["options"] if not o.get("missing")]
        for o in opts:
            if q["type"] != "age" and o.get("missing"):
                continue
            banner_cols.append((f"{bq}:{o['code']}", bq, o["code"]))

    def contains(a, codes):
        if a is None:
            return False
        if isinstance(a, frozenset):
            return bool(a & set(codes))
        return a in codes

    tables = []
    for t in plan["tables"]:
        q = qmap[t["question"]]
        opts = q["bands"] if q["type"] == "age" else q["options"]
        rows = [o for o in opts if not o.get("missing")]
        scores = {o["code"]: o.get("score") for o in opts}
        cols = []
        base_idx = [i for i, rc in enumerate(kept)
                    if rc["asked"][q["id"]] and rc["ans"][q["id"]] is not None]
        for cid, bq, code in banner_cols:
            idx = [i for i in base_idx if bq is None or kept[i]["ans"].get(bq) == code]
            wb = sum(w[i] for i in idx)
            vals = {}
            keys = [str(o["code"]) for o in rows] + [x["id"] for x in t.get("nets", [])] \
                + (["mean"] if t.get("mean") else [])
            if not idx or wb == 0:
                vals = {k: None for k in keys}
                wb = 0
            else:
                for o in rows:
                    s = sum(w[i] for i in idx if contains(kept[i]["ans"][q["id"]], [o["code"]]))
                    vals[str(o["code"])] = r2(100 * s / wb)
                for net in t.get("nets", []):
                    s = sum(w[i] for i in idx if contains(kept[i]["ans"][q["id"]], net["codes"]))
                    vals[net["id"]] = r2(100 * s / wb)
                if t.get("mean"):
                    s = sum(w[i] * scores[kept[i]["ans"][q["id"]]] for i in idx)
                    vals["mean"] = r2(s / wb)
            cols.append({"column": cid, "base": len(idx), "weighted_base": r2(wb), "values": vals})
        tables.append({"table": t["id"], "columns": cols})

    if n:
        eff = sum(w) ** 2 / sum(x * x for x in w)
        summ_w = (r2(eff), r2(min(w)), r2(max(w)))
    else:
        summ_w = (None, None, None)
    out = {
        "survey": cb["survey"],
        "summary": {
            "versions": [dict(version=v, **stats[v]) for v in versions],
            "respondents": n,
            "effective_n": summ_w[0], "weight_min": summ_w[1], "weight_max": summ_w[2],
        },
        "tables": tables,
    }
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(out, f, indent=1)


if __name__ == "__main__":
    main()
